def transform(grid):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    # Find all rows that are uniform (all cells have same value)
    uniform_rows = []
    for i in range(rows):
        if len(set(grid[i])) == 1:
            uniform_rows.append(i)

    # Find all columns that are uniform (all cells have same value)
    uniform_cols = []
    for j in range(cols):
        col_values = [grid[i][j] for i in range(rows)]
        if len(set(col_values)) == 1:
            uniform_cols.append(j)

    # Build output grid - change cells in uniform rows/cols to 2
    output = []
    for i in range(rows):
        row_output = []
        for j in range(cols):
            if i in uniform_rows or j in uniform_cols:
                row_output.append(2)
            else:
                row_output.append(grid[i][j])
        output.append(row_output)

    return output
